import{_ as s,o as n,c as o,ak as r}from"./chunks/framework.BDDxo5Ti.js";const l="/projects/ROSOrin/en/jetson-nano-version/assets/image1.C6-fOXe5.webp",h="/projects/ROSOrin/en/jetson-nano-version/assets/image2.D1fBOaSI.webp",c="data:image/png;base64,",p="/projects/ROSOrin/en/jetson-nano-version/assets/image5.Dw6sdhsV.webp",d="/projects/ROSOrin/en/jetson-nano-version/assets/image6.Z6rFE688.webp",g="/projects/ROSOrin/en/jetson-nano-version/assets/image7.vhdhRJgC.webp",m="/projects/ROSOrin/en/jetson-nano-version/assets/image8.BY5LYkqT.webp",e="/projects/ROSOrin/en/jetson-nano-version/assets/image9.C3oHvhpS.webp",u="/projects/ROSOrin/en/jetson-nano-version/assets/image10.D9QqLnQo.webp",t="data:image/png;base64,",i="/projects/ROSOrin/en/jetson-nano-version/assets/image14.Db-juz0U.webp",b="/projects/ROSOrin/en/jetson-nano-version/assets/image15.Don9okxh.webp",A="/projects/ROSOrin/en/jetson-nano-version/assets/image10.D9QqLnQo.webp",k="/projects/ROSOrin/en/jetson-nano-version/assets/image18.pKi7QFff.webp",v="/projects/ROSOrin/en/jetson-nano-version/assets/image10.D9QqLnQo.webp",f="/projects/ROSOrin/en/jetson-nano-version/assets/image20.wIHjc9G8.webp",j=JSON.parse('{"title":"3. ROS1-LiDAR Course","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3_ROS1_LiDAR_Course.md","filePath":"docs/3_ROS1_LiDAR_Course.md"}'),y={name:"docs/3_ROS1_LiDAR_Course.md"};function w(F,a,C,R,E,S){return n(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="_3-ros1-lidar-course" tabindex="-1">3. ROS1-LiDAR Course <a class="header-anchor" href="#_3-ros1-lidar-course" aria-label="Permalink to &quot;3. ROS1-LiDAR Course&quot;">​</a></h1><h2 id="_3-1-introduction-to-lidar" tabindex="-1">3.1 Introduction to LiDAR <a class="header-anchor" href="#_3-1-introduction-to-lidar" aria-label="Permalink to &quot;3.1 Introduction to LiDAR&quot;">​</a></h2><h3 id="_3-1-1-overview" tabindex="-1">3.1.1 Overview <a class="header-anchor" href="#_3-1-1-overview" aria-label="Permalink to &quot;3.1.1 Overview&quot;">​</a></h3><p>LiDAR is a high-precision, high-speed remote sensing technology essential for mapping, autonomous driving, environmental perception, and robotic navigation. This document outlines LiDAR’s principles, key components, operation, applications, advantages, and future trends.</p><p>LiDAR plays a critical role in autonomous driving and intelligent transportation, enabling real-time detection of obstacles, pedestrians, and vehicles while providing precise distance and positional information. In robotic navigation and environmental perception, LiDAR provides accurate maps and detailed information about the surrounding environment. Additionally, LiDAR is widely used in 3D modeling and mapping, security monitoring, and remote sensing surveys.</p><img loading="lazy" height="330" width="611" class="common_img" src="'+l+'"><h3 id="_3-1-2-lidar-components-and-classification" tabindex="-1">3.1.2 LiDAR Components and Classification <a class="header-anchor" href="#_3-1-2-lidar-components-and-classification" aria-label="Permalink to &quot;3.1.2 LiDAR Components and Classification&quot;">​</a></h3><p>LiDAR consists of a laser emitter, receiver and photodetector, scanning mechanism, and angle resolution system. The laser emitter generates laser beams, the receiver and photodetector capture the reflected signals, the scanning mechanism scans the surrounding environment, and the angle resolution system determines the positions of target objects.</p><p>Based on the scanning method, LiDAR can be functionally classified into the following types:</p><p>Rotating LiDAR: Rotating LiDAR achieves full scanning in the horizontal direction by rotating the emitter or scanning mechanism. It typically provides high scanning speed and measurement accuracy, which are widely used in autonomous driving, 3D environmental modeling, and mapping.</p><p>Solid-State LiDAR: Solid-State LiDAR uses a solid-state laser emitter and requires no rotating components. It is typically more compact, lightweight, and energy-efficient, making it suitable for applications such as mobile devices, drones, and robots.</p><p>Mechanical LiDAR: Mechanical LiDAR uses mechanical components to achieve laser beam scanning, such as rotating mirrors or rotating prisms. It usually has a longer measurement range and higher measurement accuracy but a slower scanning speed. Mechanical LiDAR is widely used in fields such as terrain measurement, building scanning, and navigation.</p><p>Phase-Modulated LiDAR: Phase-Modulated LiDAR measures the distance between the target object and the radar by changing the phase of the laser beam. It usually features high measurement accuracy and a large measurement range, and is widely used in fields such as map making, surveying, and industrial applications.</p><p>Flash LiDAR: Flash LiDAR uses a single short high-power laser pulse to illuminate the entire scene at once, and the reflected light signals are captured by a receiver array. It offers the advantages of high speed and high resolution, making it suitable for applications such as rapid scene capture and motion tracking.</p><h3 id="_3-1-3-lidar-version" tabindex="-1">3.1.3 LiDAR Version <a class="header-anchor" href="#_3-1-3-lidar-version" aria-label="Permalink to &quot;3.1.3 LiDAR Version&quot;">​</a></h3><p>The robot offers a variety of LiDAR options. The default LiDAR in the robot image is the MS200 LiDAR. Therefore, after receiving the robot, the LiDAR hardware should first be confirmed. Once confirmed, the LiDAR version in the image should be set to match the version of the robot&#39;s LiDAR.</p><p>LiDAR is a sensor that uses laser beams to obtain precise positional information. It has a wide range of applications in robotics, including obstacle avoidance, object following, SLAM mapping, and navigation. The robot is equipped with the MS200 LiDAR.</p><img loading="lazy" height="227" width="271" class="common_img" src="'+h+'"><p>Click the icon <img loading="lazy" height="44" width="53" class="common_img" src="'+c+'" style="display:inline;vertical-align:middle;"> on the desktop to check that the current LiDAR is MS200.</p><img loading="lazy" height="94" width="659" class="common_img" src="'+p+'"><h2 id="_3-2-working-principle-and-distance-measurement-methods" tabindex="-1">3.2 Working Principle and Distance Measurement Methods <a class="header-anchor" href="#_3-2-working-principle-and-distance-measurement-methods" aria-label="Permalink to &quot;3.2 Working Principle and Distance Measurement Methods&quot;">​</a></h2><h3 id="_3-2-1-lidar-distance-measurement" tabindex="-1">3.2.1 LiDAR Distance Measurement <a class="header-anchor" href="#_3-2-1-lidar-distance-measurement" aria-label="Permalink to &quot;3.2.1 LiDAR Distance Measurement&quot;">​</a></h3><p>There are two common methods for LiDAR to determine the distance to a target: triangulation and time-of-flight (TOF).</p><p>For TOF, as illustrated below, the LiDAR emits light toward the object, which reflects directly back to the LiDAR. The LiDAR calculates the time taken for the light to return and multiplies it by the speed of light to determine the distance between the object and the LiDAR.</p><img loading="lazy" height="311" width="820" class="common_img" src="'+d+'" style="width:600px;"><p>For triangulation, as shown below, during manufacturing, the LiDAR is adjusted so that the light does not directly hit the object but strikes at a fixed angle. This angle is preset and does not change during operation. Using trigonometric calculations with this angle, the distance from the object to the LiDAR can be determined.</p><img loading="lazy" height="313" width="809" class="common_img" src="'+g+'" style="width:600px;"><h3 id="_3-2-2-lidar-performance" tabindex="-1">3.2.2 LiDAR Performance <a class="header-anchor" href="#_3-2-2-lidar-performance" aria-label="Permalink to &quot;3.2.2 LiDAR Performance&quot;">​</a></h3><p>As illustrated below, the LiDAR emits light that illuminates the surface of an object. When the LiDAR receives the light reflected from the object, it marks the outline of the object at the positions where the light struck.</p><img loading="lazy" height="556" width="770" class="common_img" src="'+m+'" style="width:600px;"><h2 id="_3-3-lidar-obstacle-avoidance" tabindex="-1">3.3 LiDAR Obstacle Avoidance <a class="header-anchor" href="#_3-3-lidar-obstacle-avoidance" aria-label="Permalink to &quot;3.3 LiDAR Obstacle Avoidance&quot;">​</a></h2><p>The robot will detect the distance between objects directly in front and its body, and will turn left or right to avoid obstacles based on the set distance. If no obstacles are encountered, it will continue moving forward.</p><p>There are two ways to enable this feature. The first is through the mobile app, and the second is by using commands after connecting to the system remotely.</p><p>For instructions on using the app, refer to the section <a href="https://wiki.hiwonder.com/projects/ROSOrin/en/jetson-nano-version/docs/1_ROSOrin_User_Manual.html#app-control" target="_blank" rel="noreferrer">1.5.3 App Control</a> in the user manual to view the related course.</p><p>For detailed information on connecting to a remote desktop, please refer to the section <a href="https://wiki.hiwonder.com/projects/ROSOrin/en/jetson-nano-version/docs/1_ROSOrin_User_Manual.html#ap-mode-connection-steps" target="_blank" rel="noreferrer">1.7.2 AP Mode Connection Steps</a> in the user manual.</p><h3 id="_3-3-1-feature-enabling-via-app" tabindex="-1">3.3.1 Feature Enabling via App <a class="header-anchor" href="#_3-3-1-feature-enabling-via-app" aria-label="Permalink to &quot;3.3.1 Feature Enabling via App&quot;">​</a></h3><ol><li><p>Open the <strong>WonderAi</strong> app and connect to the robot.</p></li><li><p>Tap <strong>Lidar</strong> on the mode selection screen to enter the feature’s interface.</p></li></ol><img loading="lazy" height="823" width="1818" class="common_img" src="'+e+'" style="width:600px;"><ol start="3"><li>Click the switch button on the right of <strong>Avoid obstacle</strong> to activate this mode.</li></ol><img loading="lazy" height="825" width="1816" class="common_img" src="'+u+'" style="width:600px;"><ol start="4"><li>The robot will move forward, and when an obstacle is detected, it will automatically turn to avoid it.</li></ol><h3 id="_3-3-2-feature-enabling-via-command" tabindex="-1">3.3.2 Feature Enabling via Command <a class="header-anchor" href="#_3-3-2-feature-enabling-via-command" aria-label="Permalink to &quot;3.3.2 Feature Enabling via Command&quot;">​</a></h3><ol><li><p>Power on the robot and connect it via the NoMachine remote control software. For detailed information, please refer to the section <a href="https://wiki.hiwonder.com/projects/ROSOrin/en/jetson-nano-version/docs/1_ROSOrin_User_Manual.html#ap-mode-connection-steps" target="_blank" rel="noreferrer">1.7.2 AP Mode Connection Steps</a> in the user manual.</p></li><li><p>Click the terminal icon <img loading="lazy" height="38" width="45" src="'+t+'"> in the system desktop to open a command-line window.</p></li><li><p>Enter the following command and press <strong>Enter</strong> to stop the app auto-start service: The service includes functions for the wireless controller, depth camera, and other features.</p></li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start_app_node.service</span></span></code></pre></div><ol start="4"><li>Enter the command and press <strong>Enter</strong> to start the local services for the app features and chassis control.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">roslaunch bringup bringup.launch</span></span></code></pre></div><ol start="5"><li>Open another command-line terminal, enter the command, and press <strong>Enter</strong> to access the LiDAR feature:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rosservice</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /lidar_app/enter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;{}&quot;</span></span></code></pre></div><img loading="lazy" height="58" width="608" class="common_img" src="'+i+'"><ol start="6"><li>Enter the following command and press <strong>Enter</strong> to start the LiDAR feature.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rosservice</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /lidar_app/set_running</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;data: 1&quot;</span></span></code></pre></div><img loading="lazy" height="71" width="616" class="common_img" src="'+b+'"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The effect is the same as enabling the feature via the mobile app. To view the source code, the lidar.py file can be found in the /ros_ws/src/app/scripts/ folder.</strong></p></div><ol start="7"><li>To exit the feature, press <strong>Ctrl+C</strong> in the terminal used in steps 4 or 5.</li></ol><p>After the feature is closed, the app service can be activated either by using a command or by restarting the robot. If the app service is not enabled, related features in the app will not function properly. The app service will start automatically when the robot is restarted.</p><p>Enter the command to restart the app service and wait for a beep from the buzzer, indicating that the service has started.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start_app_node.service</span></span></code></pre></div><h2 id="_3-4-lidar-following" tabindex="-1">3.4 LiDAR Following <a class="header-anchor" href="#_3-4-lidar-following" aria-label="Permalink to &quot;3.4 LiDAR Following&quot;">​</a></h2><p>The robot will detect the distance between the object in front and its body. If the distance is greater than 35 cm, it will follow the object. If the distance is less than 35 cm, the robot will reverse. When the robot detects that the distance to the object in front is 35 cm, it will automatically stop.</p><p>There are two ways to enable this feature. The first is through the mobile app, and the second is by using commands after connecting to the system remotely.</p><p>For instructions on using the app, refer to Section <a href="https://wiki.hiwonder.com/projects/ROSOrin/en/jetson-nano-version/docs/1_ROSOrin_User_Manual.html#app-installation-and-connection" target="_blank" rel="noreferrer">1.5 App Installation and Connection</a> in the user manual to view the related course.</p><p>For detailed information on connecting to a remote desktop, please refer to Section <a href="https://wiki.hiwonder.com/projects/ROSOrin/en/jetson-nano-version/docs/1_ROSOrin_User_Manual.html#ap-mode-connection-steps" target="_blank" rel="noreferrer">1.7.2 AP Mode Connection Steps</a> in the user manual.</p><h3 id="_3-4-1-feature-enabling-via-app" tabindex="-1">3.4.1 Feature Enabling via App <a class="header-anchor" href="#_3-4-1-feature-enabling-via-app" aria-label="Permalink to &quot;3.4.1 Feature Enabling via App&quot;">​</a></h3><ol><li><p>Open the <strong>WonderAi</strong> app and connect to the robot.</p></li><li><p>Tap <strong>Lidar</strong> on the mode selection screen to enter the feature’s interface.</p></li></ol><img loading="lazy" height="823" width="1818" class="common_img" src="'+e+'" style="width:600px;"><ol start="3"><li>Click the switch button on the right of <strong>Lidar following</strong> to activate this mode.</li></ol><img loading="lazy" height="825" width="1816" class="common_img" src="'+A+'" style="width:600px;"><ol start="4"><li>When an obstacle is detected, the robot will adjust its position to maintain a distance of approximately 0.35 meters between its body and the obstacle.</li></ol><h3 id="_3-4-2-feature-enabling-via-command" tabindex="-1">3.4.2 Feature Enabling via Command <a class="header-anchor" href="#_3-4-2-feature-enabling-via-command" aria-label="Permalink to &quot;3.4.2 Feature Enabling via Command&quot;">​</a></h3><ol><li><p>Power on the robot and connect it via the NoMachine remote control software. For detailed information, please refer to the section <a href="https://wiki.hiwonder.com/projects/ROSOrin/en/jetson-nano-version/docs/1_ROSOrin_User_Manual.html#ap-mode-connection-steps" target="_blank" rel="noreferrer">1.7.2 AP Mode Connection Steps</a> in the user manual.</p></li><li><p>Click the terminal icon <img loading="lazy" height="38" width="45" src="'+t+'"> in the system desktop to open a command-line window.</p></li><li><p>Enter the following command and press <strong>Enter</strong> to stop the app auto-start service: The service includes functions for the wireless controller, depth camera, and other features.</p></li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start_app_node.service</span></span></code></pre></div><ol start="4"><li>Enter the command and press <strong>Enter</strong> to start the local services for the app features and chassis control.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">roslaunch bringup bringup.launch</span></span></code></pre></div><ol start="5"><li>Open another command-line terminal, enter the command, and press <strong>Enter</strong> to access the LiDAR feature:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rosservice</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /lidar_app/enter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;{}&quot;</span></span></code></pre></div><img loading="lazy" height="58" width="608" class="common_img" src="'+i+'"><ol start="6"><li>Enter the following command and press <strong>Enter</strong> to start the LiDAR following feature.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rosservice</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /lidar_app/set_running</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;data: 2&quot;</span></span></code></pre></div><img loading="lazy" height="56" width="541" class="common_img" src="'+k+'"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The effect is the same as enabling the feature via the mobile app. To view the source code, the <code>lidar.py</code> file can be found in the /ros_ws/src/app/scripts/ folder.</strong></p></div><ol start="7"><li>To exit the feature completely, press <strong>Ctrl+C</strong> in the terminal used in steps 4 or 5.</li></ol><p>After the feature is closed, the app service can be activated either by using a command or by restarting the robot. If the app service is not enabled, related features in the app will not function properly. The app service will start automatically when the robot is restarted.</p><p>Enter the command to restart the app service and wait for a beep from the buzzer, indicating that the service has started.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start_app_node.service</span></span></code></pre></div><h2 id="_3-5-lidar-guarding" tabindex="-1">3.5 LiDAR Guarding <a class="header-anchor" href="#_3-5-lidar-guarding" aria-label="Permalink to &quot;3.5 LiDAR Guarding&quot;">​</a></h2><p>The robot will detect the distance between the object in front and its body. If an object is within the set distance, the robot will steer, keeping the body always facing the object.</p><p>There are two ways to enable this feature. The first is through the app, and the second is by using commands after connecting to the system remotely.</p><p>For instructions on using the app, refer to the section <a href="https://wiki.hiwonder.com/projects/ROSOrin/en/jetson-nano-version/docs/1_ROSOrin_User_Manual.html#app-installation-and-connection" target="_blank" rel="noreferrer">1.5 App Installation and Connection</a> in the user manual to view the related course.</p><p>For detailed information on connecting to a remote desktop, please refer to the section <a href="https://wiki.hiwonder.com/projects/ROSOrin/en/jetson-nano-version/docs/1_ROSOrin_User_Manual.html#ap-mode-connection-steps" target="_blank" rel="noreferrer">1.7.2 AP Mode Connection Steps</a> in the user manual.</p><h3 id="_3-5-1-feature-enabling-via-app" tabindex="-1">3.5.1 Feature Enabling via App <a class="header-anchor" href="#_3-5-1-feature-enabling-via-app" aria-label="Permalink to &quot;3.5.1 Feature Enabling via App&quot;">​</a></h3><ol><li><p>Open the <strong>WonderAi</strong> app and connect to the robot.</p></li><li><p>Tap <strong>Lidar</strong> on the mode selection screen to enter the feature’s interface.</p></li></ol><img loading="lazy" height="823" width="1818" class="common_img" src="'+e+'" style="width:600px;"><ol start="3"><li>Click the switch button on the right of <strong><strong>Lidar guarding</strong></strong> to activate this mode.</li></ol><img loading="lazy" height="825" width="1816" class="common_img" src="'+v+'" style="width:600px;"><ol start="4"><li>When an obstacle is detected, the robot will adjust its orientation in place to face the obstacle, with the camera directly aligned with it.</li></ol><h3 id="_3-5-2-feature-enabling-via-command" tabindex="-1">3.5.2 Feature Enabling via Command <a class="header-anchor" href="#_3-5-2-feature-enabling-via-command" aria-label="Permalink to &quot;3.5.2 Feature Enabling via Command&quot;">​</a></h3><ol><li><p>Power on the robot and connect it via the NoMachine remote control software. For detailed information, please refer to the section <a href="https://wiki.hiwonder.com/projects/ROSOrin/en/jetson-nano-version/docs/1_ROSOrin_User_Manual.html#ap-mode-connection-steps" target="_blank" rel="noreferrer">1.7.2 AP Mode Connection Steps</a> in the user manual.</p></li><li><p>Click the terminal icon <img loading="lazy" height="38" width="45" src="'+t+'"> in the system desktop to open a command-line window.</p></li><li><p>Enter the following command and press <strong>Enter</strong> to stop the app auto-start service: The service includes functions for the wireless controller, depth camera, and other features.</p></li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start_app_node.service</span></span></code></pre></div><ol start="4"><li>Enter the command and press <strong>Enter</strong> to start the local services for the app features and chassis control.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">roslaunch bringup bringup.launch</span></span></code></pre></div><ol start="5"><li>Open another command-line terminal, enter the command, and press <strong>Enter</strong> to access the LiDAR feature:</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rosservice</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /lidar_app/enter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;{}&quot;</span></span></code></pre></div><img loading="lazy" height="58" width="608" class="common_img" src="'+i+'" style="width:600px;"><ol start="6"><li>Enter the following command and press <strong>Enter</strong> to start the Lidar guarding feature.</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rosservice</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> call</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /lidar_app/set_running</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;data: 3&quot;</span></span></code></pre></div><img loading="lazy" height="55" width="562" class="common_img" src="'+f+'" style="width:600px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The effect is the same as enabling the feature via the mobile app. To view the source code, the lidar.py file can be found in the /ros_ws/src/app/scripts/ folder.</strong></p></div><ol start="7"><li>To exit the feature completely, press <strong>Ctrl+C</strong> in the terminal used in steps 4 or 5.</li></ol><p>After the feature is closed, the app service can be activated either by using a command or by restarting the robot. If the app service is not enabled, related features in the app will not function properly. The app service will start automatically when the robot is restarted.</p><p>Enter the command to restart the app service and wait for a beep from the buzzer, indicating that the service has started.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start_app_node.service</span></span></code></pre></div>',111)])])}const D=s(y,[["render",w]]);export{j as __pageData,D as default};
